-- Bigger homes (docs/HUD_HOME.md "Home sizes"). Idempotent and safe on a non-empty DB; no functions, tables or
-- profiles columns change (data only: home_layouts and the geometry in house_upgrades.effect).
--   hostel 5.2 x 4.4 -> 6.2 x 5.0, face-me 4.2 x 3.8 -> 6.8 x 5.6 (the LAPO start home, now medium), self-contain
--   6 x 4.8 -> 9 x 6.8, mini-flat 9.6 x 7.2 -> 13 x 9.4, GRA duplex 14.4 x 10 -> 19 x 13.4 (more rooms, wider hall).
--   1. home_layouts: size, lot, blocks (fixtures, partitions, door zones), default slots and the pieces that came with
--      the house, generated by `node scripts/home-space-check.mjs --sql` from src/art/home3d/model.ts + arrange.ts.
--   2. house_upgrades.effect.geom: the extension rooms and yard buildings, from `node scripts/home-upgrade-check.mjs --sql`.
--   3. Saved furniture placements are re-checked in every changed layout, ONE PLAYER AT A TIME the first time they
--      load their home (the live deploy timed out when everybody was done in one statement): the migration only
--      queues the owners (home_resize_pending) and keeps the old plans (home_layouts_prev); bl_home_resize_owner(uid)
--      runs from house_upgrade_state (sign-in) and bl_furniture_materialize (every furniture action). Same rule the
--      game already uses when moving house: a piece still standing on its old default slot (or the old spot of a piece that came with the
--      house) goes to the new default spot; yard pieces and pieces in an extension room move with their side of the
--      house; any other piece stays exactly where the player put it when that is still valid. A piece that no longer
--      fits (outside the floor, inside a wall or another piece) takes the nearest free spot to where it stood, and
--      goes to My items (stored) only when nothing fits. Nobody loses furniture. A second run changes nothing.

-- ---------------------------------------------------------------- 0. remember the old plans, and who still has to be re-checked
create table if not exists public.home_layouts_prev (
  id text primary key,
  w numeric not null,
  d numeric not null,
  slots jsonb not null,
  included jsonb not null,
  queued boolean not null default false
);
alter table public.home_layouts_prev enable row level security;   -- no policies: only the definer functions read it
revoke all on public.home_layouts_prev from anon, authenticated;
create table if not exists public.home_resize_pending (
  owner_id uuid not null,
  layout text not null,
  primary key (owner_id, layout)
);
alter table public.home_resize_pending enable row level security;
revoke all on public.home_resize_pending from anon, authenticated;
-- the first run keeps the plans as they were; a second run finds them already there and changes nothing
insert into public.home_layouts_prev (id, w, d, slots, included)
select id, w, d, slots, included from public.home_layouts
on conflict (id) do nothing;

-- ---------------------------------------------------------------- 1. layouts
insert into public.home_layouts (id, w, d, lot, blocks, doors, slots, included) values
  ('hostel', 6.2, 5, '[0,0,9,6.6]'::jsonb, '[[7.05,0.55,8.15,1.65],[7.05,1.9,8.15,3],[7.3,5.1,7.9,5.7],[5.4,3.5,7,4.6]]'::jsonb, '[[5.4,3.5,7,4.6]]'::jsonb, '{"bed":[0.75,1.2,0],"seat":[4.3,4.1,0],"sofa":[2.9,3.5,3],"tv":[0.3,3.5,1],"rug":[1.7,3.5,0],"ctable":[1.55,3.5,1],"stove":[4.2,0.4,0],"fridge":[5.5,0.45,0],"wardrobe":[2.7,0.35,0],"bath":[7.6,3.8,3]}'::jsonb, '[]'::jsonb),
  ('face_me', 6.8, 5.6, '[0,0,9.8,7.2]'::jsonb, '[[7.85,0.4,8.95,1.5],[7.85,1.65,8.95,2.75],[7.6,6.23,8.4,6.78],[8.9,6.1,9.5,6.7],[6,3.9,7.6,5]]'::jsonb, '[[6,3.9,7.6,5]]'::jsonb, '{"bed":[0.85,1.2,0],"seat":[4.6,4.45,0],"sofa":[2.9,3.6,3],"tv":[0.3,3.6,1],"rug":[1.9,3.6,0],"ctable":[1.6,3.6,1],"stove":[5.25,0.4,0],"fridge":[6.4,0.45,0],"wardrobe":[3,0.35,0],"bath":[8.5,3.6,3]}'::jsonb, '[]'::jsonb),
  ('self_contain', 9, 6.8, '[0,0,11.4,8.4]'::jsonb, '[[0.28,0.2,0.73,0.9],[1.42,0.28,2.38,1.23],[0.09,1.55,0.51,2.05],[9.92,0.5,10.48,1.3],[2.54,-0.06,2.66,1.76],[-0.06,2.54,1.46,2.66],[8.2,4.9,9.8,6]]'::jsonb, '[[8.2,4.9,9.8,6]]'::jsonb, '{"bed":[7.95,1.6,3],"seat":[4.8,3.55,0],"sofa":[3,4.9,3],"tv":[0.3,4.9,1],"ctable":[1.65,4.9,1],"rug":[1.8,4.9,0],"stove":[3.7,0.4,0],"fridge":[5,0.45,0],"wardrobe":[8.7,3.7,3],"bath":[10.2,2.4,0]}'::jsonb, '[]'::jsonb),
  ('flat', 13, 9.4, '[0,0,15.2,11]'::jsonb, '[[9.63,0.2,10.07,0.9],[10.7,0.09,11.2,0.51],[11.53,0.18,12.48,1.13],[4.94,-0.06,5.06,4.26],[-0.06,4.14,3.66,4.26],[9.14,-0.06,9.26,3.26],[9.14,3.14,10.36,3.26],[11.44,3.14,13.06,3.26],[4.94,4.14,5.96,4.26],[12.2,5,13.8,6.2]]'::jsonb, '[[12.2,5,13.8,6.2]]'::jsonb, '{"bed":[1.35,1.35,0],"seat":[2.3,8.5,2],"sofa":[3.6,6.6,3],"tv":[0.3,6.6,1],"ctable":[1.8,6.6,1],"rug":[2,6.6,0],"stove":[5.9,0.4,0],"fridge":[5.45,1.9,1],"wardrobe":[4.62,1.8,3],"bath":[9.8,2.2,1]}'::jsonb, '[{"id":"cab","furniture":"kitchen_cabinet","kind":"kitchen_cab","x":7.4,"z":0.33,"rot":0},{"id":"ac","furniture":"ac_split","kind":"ac","x":1.4,"z":0.15,"rot":0},{"id":"cfan","furniture":"fan_ceiling","kind":"fan_ceiling","x":2,"z":6.6,"rot":0},{"id":"dining","furniture":"dining_4","kind":"dining4","x":9.9,"z":6.4,"rot":0},{"id":"gen","furniture":"gen_firman","kind":"generator","x":14.2,"z":1.4,"rot":1}]'::jsonb),
  ('duplex', 19, 13.4, '[-1,-0.5,23.2,18]'::jsonb, '[[12.53,0.2,12.98,0.9],[13.5,0.09,14,0.51],[14.45,0.45,15.25,2.15],[7.9,0.04,10.1,0.66],[8.2,2.1,9.8,2.9],[17.95,0.3,18.95,2.9],[5.94,-0.06,6.06,5.06],[-0.06,4.94,4.46,5.06],[12.14,-0.06,12.26,3.66],[12.14,3.54,13.46,3.66],[14.54,3.54,15.46,3.66],[15.34,-0.06,15.46,3.66],[15.34,3.54,16.06,3.66],[15.14,6.54,19.06,6.66],[15.14,6.54,15.26,7.46],[15.14,8.54,15.26,9.86],[13.54,9.74,19.06,9.86],[13.54,9.74,13.66,10.86],[13.54,11.94,13.66,13.46],[9.54,10.74,9.66,13.46],[7,12.6,8.4,14.2],[18.2,4.6,19.8,5.9]]'::jsonb, '[[7,12.6,8.4,14.2],[18.2,4.6,19.8,5.9]]'::jsonb, '{"bed":[1.6,1.5,0],"seat":[2.4,11.9,2],"sofa":[4.2,9.4,3],"tv":[0.3,9.4,1],"ctable":[2.1,9.4,1],"rug":[2.3,9.4,0],"stove":[6.9,0.4,0],"fridge":[6.4,2,1],"wardrobe":[4,0.35,0],"bath":[13.2,2.4,1]}'::jsonb, '[{"id":"heater","furniture":"water_heater","kind":"water_heater","x":14.5,"z":0.15,"rot":0},{"id":"cab","furniture":"kitchen_cabinet","kind":"kitchen_cab","x":11.2,"z":0.33,"rot":0},{"id":"washer","furniture":"washing_machine","kind":"washer","x":16,"z":0.45,"rot":0},{"id":"ac1","furniture":"ac_split","kind":"ac","x":1.6,"z":0.15,"rot":0},{"id":"ac2","furniture":"ac_split","kind":"ac","x":0.15,"z":7.6,"rot":1},{"id":"chand","furniture":"chandelier","kind":"chandelier","x":2.3,"z":9.4,"rot":0},{"id":"cfan","furniture":"fan_ceiling","kind":"fan_ceiling","x":11.4,"z":8.8,"rot":0},{"id":"dining","furniture":"dining_6","kind":"dining6","x":11.4,"z":8.8,"rot":0},{"id":"gbed","furniture":"bed_double","kind":"bed_double","x":18,"z":11.6,"rot":3},{"id":"gside","furniture":"bedside","kind":"bedside","x":18.5,"z":10.4,"rot":0},{"id":"gward","furniture":"wardrobe_big","kind":"wardrobe_big","x":15.1,"z":13.05,"rot":2},{"id":"gen","furniture":"gen_firman","kind":"generator","x":21.2,"z":1.2,"rot":1},{"id":"palm1","furniture":"plant_palm","kind":"plant_big","x":-0.5,"z":17.2,"rot":0},{"id":"palm2","furniture":"plant_palm","kind":"plant_big","x":22.6,"z":5.2,"rot":0}]'::jsonb)
on conflict (id) do update set w = excluded.w, d = excluded.d, lot = excluded.lot, blocks = excluded.blocks,
  doors = excluded.doors, slots = excluded.slots, included = excluded.included;

-- every included piece must be a catalogue row of the same 3D kind (the client draws the owned copy by kind)
do $mig$
declare v text;
begin
  select string_agg(i->>'furniture', ', ') into v
    from public.home_layouts hl, jsonb_array_elements(hl.included) i
   where not exists (select 1 from public.furniture f where f.id = i->>'furniture' and f.kind = i->>'kind');
  if v is not null then raise exception 'bigger homes: included pieces missing from the furniture catalogue: %', v; end if;
end $mig$;

-- ---------------------------------------------------------------- 2. extension rooms and yard buildings
update public.house_upgrades u set effect = jsonb_set(u.effect, '{geom}', g.geom, true)
  from (values
    ('ext_bedroom', '{"face_me":{"room":{"rect":[0,5.6,6.8,8.8],"door":[3.2,4.4]}},"self_contain":{"room":{"rect":[0,6.8,7.2,10],"door":[3.4,4.6]}},"flat":{"room":{"rect":[0,9.4,8,12.8],"door":[3.4,4.6]}}}'::jsonb),
    ('ext_guest_wing', '{"duplex":{"room":{"rect":[9,13.4,19,17.2],"door":[10.2,11.4]}}}'::jsonb),
    ('boys_quarters', '{"duplex":{"struct":{"kind":"bq","rect":[20,7.2,23.2,9.6]}}}'::jsonb),
    ('gen_house', '{"face_me":{"struct":{"kind":"genhouse","rect":[9.4,0.4,10.7,1.4]}},"self_contain":{"struct":{"kind":"genhouse","rect":[10.9,0.4,12.2,1.4]}},"flat":{"struct":{"kind":"genhouse","rect":[14.9,0.4,16.2,1.4]}},"duplex":{"struct":{"kind":"genhouse","rect":[21.9,-0.1,23.2,0.9]}}}'::jsonb),
    ('solar_system', '{"face_me":{"struct":{"kind":"solar","rect":[9.9,5.9,11.9,7]}},"self_contain":{"struct":{"kind":"solar","rect":[11.15,6.9,13.15,8]}},"flat":{"struct":{"kind":"solar","rect":[13.4,9.65,15.4,10.75]}},"duplex":{"struct":{"kind":"solar","rect":[21.15,11.9,23.15,13]}}}'::jsonb),
    ('borehole', '{"face_me":{"struct":{"kind":"borehole","rect":[9.4,2.15,11,3.35]}},"self_contain":{"struct":{"kind":"borehole","rect":[9.9,3.15,11.5,4.35]}},"flat":{"struct":{"kind":"borehole","rect":[13.65,3.15,15.25,4.35]}},"duplex":{"struct":{"kind":"borehole","rect":[20.6,2.4,22.2,3.6]}}}'::jsonb)
  ) as g(id, geom) where u.id = g.id;

-- ---------------------------------------------------------------- 2b. queue the owners (once per resized layout)
insert into public.home_resize_pending (owner_id, layout)
select distinct h.owner_id, h.layout
  from public.player_house_furniture h
  join public.home_layouts_prev p on p.id = h.layout and not p.queued
  join public.home_layouts n on n.id = h.layout and (n.w, n.d) is distinct from (p.w, p.d)
 where not h.stored
on conflict do nothing;
update public.home_layouts_prev p set queued = true;

-- ---------------------------------------------------------------- 3. saved furniture placements
-- p_old = the layouts as they were before the resize: [{id, w, d, slots, included}]. Returns how many homes were re-checked.
-- Layouts whose size did not change are skipped, so running it again changes nothing. p_owner = only that player.
drop function if exists public.bl_homes_replace_after_resize(jsonb);
create or replace function public.bl_homes_replace_after_resize(p_old jsonb, p_owner uuid default null) returns integer
language plpgsql security definer set search_path = public as $$
declare
  o record;
  r record;
  hl public.home_layouts;
  old jsonb;
  v_ow numeric;
  v_od numeric;
  v_n integer := 0;
  v_new jsonb;
  v_x numeric;
  v_z numeric;
  v_rot int;
  v_slot jsonb;
begin
  create temp table if not exists bl_big_rows (key text, tx numeric, tz numeric, trot int, moved boolean, at timestamptz) on commit drop;
  for o in select distinct h.owner_id, h.layout from public.player_house_furniture h
            join public.home_layouts n on n.id = h.layout
           where not h.stored and (p_owner is null or h.owner_id = p_owner)
             and exists (select 1 from jsonb_array_elements(p_old) e
                          where e->>'id' = h.layout and ((e->>'w')::numeric, (e->>'d')::numeric) is distinct from (n.w, n.d)) loop
    select * into hl from public.home_layouts where id = o.layout;
    select e into old from jsonb_array_elements(p_old) e where e->>'id' = o.layout;
    v_ow := (old->>'w')::numeric; v_od := (old->>'d')::numeric;
    truncate bl_big_rows;
    for r in select h.furniture_key, h.x, h.z, h.rotation, h.updated_at,
                    coalesce(pf.slot, f.slot) as slot, bl_furniture_id_of(h.furniture_key) as fid
               from public.player_house_furniture h
               left join public.player_furniture pf on pf.user_id = h.owner_id and pf.furniture_id = bl_furniture_id_of(h.furniture_key)
               left join public.furniture f on f.id = bl_furniture_id_of(h.furniture_key)
              where h.owner_id = o.owner_id and h.layout = o.layout and not h.stored loop
      v_new := null;
      -- still on the old default slot -> the new default slot
      v_slot := old->'slots'->r.slot;
      if v_slot is not null and (v_slot->>0)::numeric = r.x and (v_slot->>1)::numeric = r.z
         and (((v_slot->>2)::int % 4) + 4) % 4 = r.rotation and hl.slots ? r.slot and bl_furniture_copy_of(r.furniture_key) = 1 then
        v_new := hl.slots->r.slot;
        v_x := (v_new->>0)::numeric; v_z := (v_new->>1)::numeric; v_rot := (v_new->>2)::int;
      else
        -- still on the old spot of a piece that came with the house -> its new spot
        select n into v_new from jsonb_array_elements(hl.included) n
         where n->>'furniture' = r.fid
           and exists (select 1 from jsonb_array_elements(old->'included') i
                        where i->>'id' = n->>'id' and i->>'furniture' = r.fid
                          and (i->>'x')::numeric = r.x and (i->>'z')::numeric = r.z)
         limit 1;
        if v_new is not null then
          v_x := (v_new->>'x')::numeric; v_z := (v_new->>'z')::numeric; v_rot := coalesce((v_new->>'rot')::int, 0);
        else
          -- the east yard moves with the east wall, the south yard and the extension rooms with the south wall
          v_x := r.x + case when r.x >= v_ow then hl.w - v_ow when o.layout = 'duplex' and r.z >= v_od then 1.6 else 0 end;
          v_z := r.z + case when r.z >= v_od then hl.d - v_od else 0 end;
          v_rot := r.rotation;
        end if;
      end if;
      insert into bl_big_rows values (r.furniture_key, v_x, v_z, ((v_rot % 4) + 4) % 4, v_new is not null, r.updated_at);
    end loop;
    -- take them all out, then put them back one by one: the pieces the player placed first (oldest first, exact spot
    -- when it is still valid, else the nearest free spot), then the pieces that follow their default slot, so each
    -- check only sees pieces that already stand; a piece that fits nowhere waits in My items
    update public.player_house_furniture set stored = true where owner_id = o.owner_id and layout = o.layout and not stored;
    for r in select * from bl_big_rows order by moved, at, key loop
      perform public.bl_furniture_autoplace(o.owner_id, o.layout, r.key, r.tx, r.tz, r.trot, true);
    end loop;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;
revoke execute on function public.bl_homes_replace_after_resize(jsonb, uuid) from public, anon, authenticated;

-- one player, the first time they load their home: cheap when nothing is queued (one primary-key lookup)
create or replace function public.bl_home_resize_owner(p_uid uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare v_n integer;
begin
  if not exists (select 1 from home_resize_pending where owner_id = p_uid) then return 0; end if;
  delete from home_resize_pending where owner_id = p_uid;   -- a second tab waits here, then finds nothing
  select public.bl_homes_replace_after_resize(
           (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'w', w, 'd', d, 'slots', slots, 'included', included)), '[]'::jsonb)
              from home_layouts_prev), p_uid) into v_n;
  return coalesce(v_n, 0);
end $$;
revoke execute on function public.bl_home_resize_owner(uuid) from public, anon, authenticated;

-- hooks (guarded: skipped when already applied, an error when the function changed shape)
create or replace function pg_temp.bh_patch(p_fn regprocedure, p_from text, p_to text) returns void
language plpgsql as $$
declare v_def text;
begin
  v_def := pg_get_functiondef(p_fn);
  if position('bl_home_resize_owner' in v_def) > 0 then return; end if;
  if position(p_from in v_def) = 0 then raise exception 'bigger homes: anchor not found in %', p_fn; end if;
  execute replace(v_def, p_from, p_to);
end $$;
select pg_temp.bh_patch('public.bl_furniture_materialize(uuid)'::regprocedure,
  E'begin\n  perform bl_house_items_grant(p_uid);',
  E'begin\n  perform public.bl_home_resize_owner(p_uid); -- bigger homes: re-place this player''s furniture once\n  perform bl_house_items_grant(p_uid);');
select pg_temp.bh_patch('public.house_upgrade_state()'::regprocedure,
  E'begin\n  perform bl_house_upgrades_settle(v_me.id);',
  E'begin\n  perform public.bl_home_resize_owner(v_me.id); -- bigger homes: re-place this player''s furniture once (sign-in)\n  perform bl_house_upgrades_settle(v_me.id);');

notify pgrst, 'reload schema';
